gWo(){return"\ud68c\ubcf5\uc740 \ub300\uc0c1\uc758 \ucd5c\ub300 <hp>\uccb4\ub825</hp> \uc77c\ubd80\ub97c \uc989\uc2dc \ub418\ub3cc\ub824\uc694. <hp>\uccb4\ub825</hp>\uc740 \ucd5c\ub300\uce58\ub97c \ub118\uc9c0 \uc54a\uc544\uc694."},
