gvi(){return"\uc11d\ud654\uc758 \ub208\ube5b: \ub208\ube5b\uc774 \uac00\uc7a5 \uac15\ud55c Ovaling\uc744 <fx:petrify>\ub3cc</fx>\ub85c \ub9cc\ub4e4\uc5b4\uc694. <fx:heal>\ud68c\ubcf5</fx>\ud558\uac70\ub098 <fx:cleanse>\uc815\ud654</fx>\ud558\uba74 \ub2e4\uc2dc \ud480\ub824\ub098\uc694."},
